<script setup>
import {ref,computed,watch} from 'vue';import {useRoute,useRouter,RouterLink} from 'vue-router';import {api} from '../lib/api';import {notice} from '../lib/state';import {date,obraPath} from '../lib/format';import EditorForm from '../components/EditorForm.vue';import PageCard from '../components/PageCard.vue';
const route=useRoute(),router=useRouter(),data=ref(null),error=ref(''),saving=ref(false);
const base=computed(()=>`/obras/${route.params.obraId}/informes/${route.params.pk}`);
async function load(){try{data.value=await api.get(base.value)}catch(e){error.value=e.message}}
watch(()=>route.fullPath,load,{immediate:true});
async function save(values){saving.value=true;try{await api.put(base.value,values);notice('Informe guardado');await load()}catch(e){error.value=e.message}finally{saving.value=false}}
async function action(which,values={}){if(which==='delete'&&!confirm('¿Eliminar informe?'))return;if(which==='emit'&&!confirm('¿Emitir PDF y cerrar edición?'))return;saving.value=true;try{if(which==='delete'){await api.del(base.value);router.push(obraPath(route.params.obraId,'informes'));return;}await api.post(base.value,{action:which,...values});notice('Cambios guardados');await load()}catch(e){error.value=e.message}finally{saving.value=false}}
async function savePhoto(row){await action('photo',{foto:row.photo.id,incluir:row.included,seccion:row.section,orden:row.order||0})}
</script>
<template><div class="page-heading page-heading--module"><div class="page-heading__titles"><h2 class="page-title display">{{data?.report?.titulo||'Informe'}}</h2><p class="page-description">Semana {{data?.report?.semana_id}} · Corte {{date(data?.report?.fecha_corte)}} · {{data?.report?.estado}}</p></div><div class="page-actions"><RouterLink class="btn" :to="obraPath(route.params.obraId,'informes')">← Informes</RouterLink><a v-if="data?.report?.pdf_path" class="btn btn-primary" :href="api.pdf(route.params.obraId,route.params.pk)" target="_blank" rel="noopener">Ver PDF</a></div></div>
<p v-if="error" class="notice bad">{{error}}</p><template v-if="data"><PageCard title="Contenido del informe" description="Datos para la generación del documento semanal"><EditorForm :schema="data.schema" :disabled="!data.editable" :saving="saving" @submit="save"/></PageCard>
<PageCard title="Selección de fotografías" description="Define las imágenes incluidas y su sección en el informe"><div class="photo-grid" style="display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:14px"><article v-for="r in data.batch?.all||[]" :key="r.photo.id" class="card" style="padding:12px"><img :src="api.file(r.photo.storage_path)" :alt="r.photo.caption||'Foto de obra'" loading="lazy" style="width:100%;aspect-ratio:4/3;object-fit:cover"/><div class="field"><label><input v-model="r.included" type="checkbox" :disabled="!data.editable"/> Incluir en informe</label></div><div class="field"><label>Sección</label><select v-model="r.section" :disabled="!data.editable"><option value="obra">Trabajos</option><option value="problema">Problemas</option></select></div><div class="field"><label>Orden</label><input v-model.number="r.order" type="number" :disabled="!data.editable"/></div><button v-if="data.editable" class="btn btn-sm" @click="savePhoto(r)">Guardar fotografía</button></article></div><p v-if="!data.batch?.all?.length">No hay fotografías para esta obra.</p></PageCard>
<PageCard title="Acciones del informe"><div class="page-actions"><button v-if="data.editable" class="btn btn-primary" :disabled="saving" @click="action('emit')">Emitir PDF</button><button v-if="data.report.estado==='emitido'" class="btn" :disabled="saving" @click="action('reopen')">Reabrir para editar</button><button v-if="data.editable" class="btn" :disabled="saving" @click="action('reset_photos')">Restablecer fotografías</button><button class="btn btn-ghost" :disabled="saving" @click="action('delete')">Eliminar informe</button></div></PageCard></template></template>
